def build_agent(sandbox):
    cabin = sandbox.get_vehicle_cabin()
    # Add 4 beams within the build zone (x=4.8-9.0, y=2.0-3.2)
    # Beam dimensions: width=1.4, height=2.0, density=1.0 (mass=2.8 kg each)
    beam1 = sandbox.add_beam(x=5.2, y=2.5, width=1.4, height=2.0, density=1.0)
    beam2 = sandbox.add_beam(x=5.2, y=3.0, width=1.4, height=2.0, density=1.0)
    beam3 = sandbox.add_beam(x=6.0, y=2.5, width=1.4, height=2.0, density=1.0)
    beam4 = sandbox.add_beam(x=6.0, y=3.0, width=1.4, height=2.0, density=1.0)
    # Attach beams to the cart using rigid joints
    sandbox.add_joint(cabin, beam1, anchor_point=(5.2, 2.5), type='rigid')
    sandbox.add_joint(cabin, beam2, anchor_point=(5.2, 3.0), type='rigid')
    sandbox.add_joint(cabin, beam3, anchor_point=(6.0, 2.5), type='rigid')
    sandbox.add_joint(cabin, beam4, anchor_point=(6.0, 3.0), type='rigid')
    return cabin

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_vehicle_position()
    vel = sandbox.get_vehicle_velocity()
    vx, vy = vel

    # Apply forces in impulse zones
    if 8.0 <= pos[0] <= 9.0:
        # First impulse zone: apply boost to meet speed trap at x=9.0
        if vx < 2.8:
            sandbox.apply_force(agent_body, (1200.0, 0.0))
    elif 10.5 <= pos[0] <= 11.0:
        # Second impulse zone: apply force for gates 2 and 3
        # Calculate time to reach gate 3 (x=11.75)
        distance_to_gate3 = 11.75 - pos[0]
        time_to_gate3 = distance_to_gate3 / vx if vx != 0 else 0
        # Gate 3's open window is from t=0.5 to 0.5 + (2π/1.2) ≈ 0.5 + 5.23 ≈ 5.73 seconds
        # Assume we need to arrive at gate3 around t=1.0 seconds
        if time_to_gate3 > 0.5:
            if vx < 2.0:
                sandbox.apply_force(agent_body, (500.0, 0.0))
            elif vx > 3.0:
                sandbox.apply_force(agent_body, (-500.0, 0.0))
    elif 9.5 <= pos[0] <= 11.0:
        # Decel zone: adjust speed for checkpoint and gates
        # Check checkpoint at x=11.0
        if vx < 1.1:
            sandbox.apply_force(agent_body, (600.0, 0.0))
        elif vx > 2.7:
            sandbox.apply_force(agent_body, (-600.0, 0.0))
        # Adjust speed for gate 2 (x=11.5)
        distance_to_gate2 = 11.5 - pos[0]
        time_to_gate2 = distance_to_gate2 / vx if vx != 0 else 0
        if pos[0] > 11.5 and pos[0] < 11.75:
            if vx < 1.5:
                sandbox.apply_force(agent_body, (500.0, 0.0))
            elif vx > 2.5:
                sandbox.apply_force(agent_body, (-500.0, 0.0))

    # Check speed trap at x=9.0
    if abs(pos[0] - 9.0) < 0.1:
        if vx < 2.8:
            sandbox.apply_force(agent_body, (1200.0, 0.0))
    # Check checkpoint at x=11.0
    if abs(pos[0] - 11.0) < 0.1:
        if vx < 1.1:
            sandbox.apply_force(agent_body, (600.0, 0.0))
        elif vx > 2.7:
            sandbox.apply_force(agent_body, (-600.0, 0.0))
